// Process security threats
const input = $input.first().json;
const threats = input.threats || [];
const summary = input.summary || { total: 0, critical: 0, high: 0, medium: 0 };

const criticalThreats = threats.filter(t => t.severity === 'critical');
const highThreats = threats.filter(t => t.severity === 'high');

// Format threats for Slack
const formatThreat = (threat) => {
  return `• *${threat.type.replace('_', ' ').toUpperCase()}*\n  User: ${threat.user_email || threat.ip_address || 'Unknown'}\n  Evidence: ${threat.evidence[0] || 'N/A'}\n  Action: ${threat.recommended_action}`;
};

const criticalMessages = criticalThreats.map(formatThreat).join('\n\n');
const highMessages = highThreats.map(formatThreat).join('\n\n');

return [{
  json: {
    hasThreats: threats.length > 0,
    hasCritical: criticalThreats.length > 0,
    hasHigh: highThreats.length > 0,
    summary,
    criticalThreats,
    highThreats,
    criticalMessages: criticalMessages || 'None',
    highMessages: highMessages || 'None',
    allThreats: threats,
    timestamp: new Date().toISOString()
  }
}];

